`, "",{"version":3,"sources":["webpack://./src/潮汐预设脚本/ModalDialog.vue"],"names":[],"mappings":"AA0EA,uCACE,cAAe,CACf,OAAQ,CACR,0BAA8B,CAC9B,YAAa,CACb,kBAAmB,CACnB,sBAAuB,CACvB,aAAc,CACd,YAAa,CACb,qBACF,CAEA,+BACE,WAAY,CACZ,cAAe,CACf,eAAgB,CAChB,kBAAmB,CACnB,qCAAyC,CACzC,kBAAmB,CACnB,eAAgB,CAChB,sCAA0C,CAC1C,WACF,CAEA,sCACE,mBACF,CAEA,qCACE,cAAe,CACf,eAAgB,CAChB,2BACF,CAEA,oCACE,sBACF,CAEA,uCACE,cAAe,CACf,2BAA+B,CAC/B,eAAgB,CAChB,eACF,CAEA,qCACE,UAAW,CACX,gBAAiB,CACjB,qCAAyC,CACzC,iBAAkB,CAClB,2BAA+B,CAC/B,2BAA+B,CAC/B,cAAe,CACf,YAAa,CACb,qBACF,CACA,2CACE,oBAAqB,CACrB,yCACF,CAEA,sCACE,YAAa,CACb,wBAAyB,CACzB,OAAQ,CACR,mBACF,CAEA,mCACE,gBAAiB,CACjB,iBAAkB,CAClB,cAAe,CACf,eAAgB,CAChB,cAAe,CACf,oBACF,CAEA,0CACE,uCAA2C,CAC3C,iCAAqC,CACrC,2BACF,CACA,gDACE,iCAAqC,CACrC,2BACF,CAEA,sCACE,qCAAyC,CACzC,gCAAoC,CACpC,aACF,CACA,4CACE,gCACF,CAGA,wFAEE,4BACF,CACA,kFAEE,SACF","sourcesContent":["<template>\n  <Transition name=\"chaoxi-modal\">\n    <div v-if=\"visible\" class=\"chaoxi-modal-overlay\" @click.self=\"onCancel\">\n      <div class=\"chaoxi-modal\">\n        <div class=\"chaoxi-modal-header\">\n          <span class=\"chaoxi-modal-title\">{{ title }}</span>\n        </div>\n        <div class=\"chaoxi-modal-body\">\n          <p v-if=\"message\" class=\"chaoxi-modal-message\">{{ message }}</p>\n          <input\n            v-if=\"mode === 'prompt'\"\n            ref=\"inputRef\"\n            class=\"chaoxi-modal-input\"\n            v-model=\"inputValue\"\n            @keydown.enter=\"onConfirm\"\n            @keydown.escape=\"onCancel\"\n            spellcheck=\"false\"\n          />\n        </div>\n        <div class=\"chaoxi-modal-footer\">\n          <button class=\"chaoxi-modal-btn chaoxi-modal-btn-cancel\" @click=\"onCancel\">取消</button>\n          <button class=\"chaoxi-modal-btn chaoxi-modal-btn-ok\" @click=\"onConfirm\">确定</button>\n        </div>\n      </div>\n    </div>\n  </Transition>\n</template>\n\n<script setup lang=\"ts\">\nconst props = defineProps<{\n  visible: boolean;\n  title: string;\n  message?: string;\n  mode: 'confirm' | 'prompt';\n  defaultValue?: string;\n}>();\n\nconst emit = defineEmits<{\n  confirm: [value: string | true];\n  cancel: [];\n}>();\n\nconst inputRef = ref<HTMLInputElement | null>(null);\nconst inputValue = ref('');\n\nwatch(\n  () => props.visible,\n  val => {\n    if (val) {\n      inputValue.value = props.defaultValue ?? '';\n      nextTick(() => {\n        inputRef.value?.focus();\n        inputRef.value?.select();\n      });\n    }\n  },\n);\n\nfunction onConfirm() {\n  if (props.mode === 'prompt') {\n    const v = inputValue.value.trim();\n    if (!v) return;\n    emit('confirm', v);\n  } else {\n    emit('confirm', true);\n  }\n}\n\nfunction onCancel() {\n  emit('cancel');\n}\n</script>\n\n<style scoped>\n.chaoxi-modal-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.6);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 10001;\n  padding: 20px;\n  box-sizing: border-box;\n}\n\n.chaoxi-modal {\n  width: 340px;\n  max-width: 90vw;\n  max-height: 80vh;\n  background: #0a0e1a;\n  border: 1px solid rgba(77, 201, 246, 0.2);\n  border-radius: 12px;\n  overflow: hidden;\n  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.6);\n  margin: auto;\n}\n\n.chaoxi-modal-header {\n  padding: 14px 18px 0;\n}\n\n.chaoxi-modal-title {\n  font-size: 14px;\n  font-weight: 600;\n  color: rgba(255, 255, 255, 0.9);\n}\n\n.chaoxi-modal-body {\n  padding: 12px 18px 16px;\n}\n\n.chaoxi-modal-message {\n  font-size: 13px;\n  color: rgba(255, 255, 255, 0.6);\n  margin: 0 0 12px;\n  line-height: 1.5;\n}\n\n.chaoxi-modal-input {\n  width: 100%;\n  padding: 8px 12px;\n  border: 1px solid rgba(77, 201, 246, 0.2);\n  border-radius: 6px;\n  background: rgba(5, 8, 16, 0.8);\n  color: rgba(255, 255, 255, 0.9);\n  font-size: 13px;\n  outline: none;\n  box-sizing: border-box;\n}\n.chaoxi-modal-input:focus {\n  border-color: #4dc9f6;\n  box-shadow: 0 0 0 2px rgba(77, 201, 246, 0.1);\n}\n\n.chaoxi-modal-footer {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n  padding: 0 18px 14px;\n}\n\n.chaoxi-modal-btn {\n  padding: 6px 20px;\n  border-radius: 6px;\n  font-size: 12px;\n  font-weight: 500;\n  cursor: pointer;\n  transition: all 0.15s;\n}\n\n.chaoxi-modal-btn-cancel {\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  background: rgba(255, 255, 255, 0.04);\n  color: rgba(255, 255, 255, 0.5);\n}\n.chaoxi-modal-btn-cancel:hover {\n  background: rgba(255, 255, 255, 0.08);\n  color: rgba(255, 255, 255, 0.8);\n}\n\n.chaoxi-modal-btn-ok {\n  border: 1px solid rgba(77, 201, 246, 0.3);\n  background: rgba(77, 201, 246, 0.15);\n  color: #4dc9f6;\n}\n.chaoxi-modal-btn-ok:hover {\n  background: rgba(77, 201, 246, 0.25);\n}\n\n/* 过渡 */\n.chaoxi-modal-enter-active,\n.chaoxi-modal-leave-active {\n  transition: opacity 0.2s ease;\n}\n.chaoxi-modal-enter-from,\n.chaoxi-modal-leave-to {\n  opacity: 0;\n}\n</style>\n"],"sourceRoot":""}]);
